import {t} from "vy/i18n";import {all,put,remove} from "vy/database";import {uid,toast,modal,closeModal} from "vy/ui";import {IC} from "vy/art";
export const DAYS_AR=["الأحد","الإثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"];
const isoW=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
export function weekState(sched,ws){const now=new Date(),ti=now.getDay(),s0=new Date(now);s0.setHours(0,0,0,0);s0.setDate(now.getDate()-ti);const dd=new Set(ws.map(x=>x.date)),pl=new Set(sched.map(x=>x.day));let nxt=-1;
const days=DAYS_AR.map((ar,i)=>{const d=new Date(s0);d.setDate(s0.getDate()+i);const done=dd.has(isoW(d)),planned=pl.has(ar);let st="rest";if(done)st="done";else if(planned&&i>=ti){if(nxt<0)nxt=i;st=nxt===i?"upcoming":"planned"}else if(planned)st="missed";return{i,ar,date:isoW(d),planned,done,st,today:i===ti}});
const goal=pl.size,doneN=days.filter(d=>d.done).length;return{days,goal,doneN,pct:goal?Math.min(100,Math.round(days.filter(d=>d.done&&(d.planned||true)).length/goal*100)):0,next:days.find(d=>d.st==="upcoming"),s0}}
const ICON={done:"✓",planned:"✓",upcoming:"🕒",missed:"!",rest:""};
export async function weekPage(){const sc=await all("schedule"),ws=await all("workouts"),W=weekState(sc,ws),L=t("days");
const prev=[1,2,3,4].map(n=>{const a=new Date(W.s0);a.setDate(a.getDate()-7*n);const b=new Date(a);b.setDate(a.getDate()+6);return ws.filter(x=>x.date>=isoW(a)&&x.date<=isoW(b)).length});
return `<section class="wk"><div class="wk-top"><button class="wk-back" data-page="home" aria-label="${t("back")}">❮</button><img src="data:image/jpeg;base64," alt=""><div class="wk-ttl"><i>${IC.calendar}</i><div><h1>${t("wTitle")}</h1><small>${t("wSub")}</small></div></div></div>
<div class="wk-days">${W.days.map(d=>`<button class="wkd ${d.st} ${d.today?"is-today":""}" data-wkday="${d.ar}"><i class="cal">${IC.calendar}</i><b>${L[d.i]}</b><span class="dot">${ICON[d.st]}</span><em>${d.done?t("done"):d.st==="upcoming"?t("upcoming"):d.st==="planned"?t("planned"):d.st==="missed"?t("missed"):t("rest")}</em></button>`).join("")}</div>
<p class="wk-hint">💡 ${t("hint")}</p>
<div class="wk-grid"><div class="wk-card"><h3>ⓘ ${t("guide")}</h3><ul class="wk-lg"><li><i class="planned">✓</i>${t("gPlanned")}</li><li><i class="done">🏆</i>${t("gDone")}</li><li><i class="upcoming">🕒</i>${t("gUp")}</li><li><i class="rest"></i>${t("gRest")}</li></ul></div>
<div class="wk-card"><h3>${t("wStats")}</h3><div class="wk-st"><div class="rg" style="--p:${W.pct}"><b dir="ltr">${W.pct}%</b></div><div><b dir="ltr">${W.doneN} / ${W.goal}</b><small>${t("wSess")}</small><b dir="ltr">${W.goal}</b><small>${t("wDays")} ${t("of7")}</small></div></div></div>
<div class="wk-card"><h3>⭐ ${t("why")}</h3><ul class="wk-ok"><li>${t("w1")}</li><li>${t("w2")}</li><li>${t("w3")}</li></ul></div>
<div class="wk-act"><button class="primary-btn" data-wk="edit">⚙ ${t("edit")}</button><button class="secondary-btn" data-wk="reset">⟳ ${t("reset")}</button></div></div>
<p class="muted wk-prev">${t("prev")}: ${prev.map(n=>`<b dir="ltr">${n}</b>`).join(" • ")}</p></section>`}
const PAT={2:[1,4],3:[1,3,5],4:[1,2,4,5],5:[1,2,3,5,6],6:[0,1,2,4,5,6]};
async function setDays(idx){for(const x of await all("schedule"))await remove("schedule",x.id);for(const i of idx)await put("schedule",{id:uid(),day:DAYS_AR[i],name:t("planned")})}
export function bindWeek(render){document.addEventListener("click",async e=>{const d=e.target.closest("[data-wkday]");if(d){const ex=(await all("schedule")).filter(x=>x.day===d.dataset.wkday);if(ex.length)for(const x of ex)await remove("schedule",x.id);else await put("schedule",{id:uid(),day:d.dataset.wkday,name:t("planned")});render("schedule");return}
const a=e.target.closest("[data-wk]");if(!a)return;if(a.dataset.wk==="reset"&&confirm(t("confirmReset"))){await setDays([]);render("schedule")}
if(a.dataset.wk==="edit")modal(t("edit"),`<form id="autoForm" class="form-grid"><div class="field full"><label>${t("auto")} — ${t("perWeek")}</label><select name="n">${[2,3,4,5,6].map(n=>`<option ${n===3?"selected":""}>${n}</option>`).join("")}</select></div><button class="primary-btn full">${t("apply")}</button></form>`)});
document.addEventListener("submit",async e=>{if(e.target.id!=="autoForm")return;e.preventDefault();await setDays(PAT[+e.target.n.value]);closeModal();toast("✓");render("schedule")})}
